        others => X"000" 
    );

    -- Señales internas
    signal current_frame : integer range 0 to NUM_FRAMES-1 := 0;
    signal block_x, block_y : integer;
    signal rom_address : integer;
    signal color_data : std_logic_vector(11 downto 0);

begin

    -- PROCESO 1: GESTIÓN DE FRAMES (ANIMACIÓN)
    process(clk)
    begin
        if rising_edge(clk) then
            if tick_cambio_frame = '1' then
                if current_frame = NUM_FRAMES - 1 then
                    current_frame <= 0; -- Volver al principio (Loop)
                else
                    current_frame <= current_frame + 1; -- Siguiente frame
                end if;
            end if;
        end if;
    end process;

    -- PROCESO 2: LECTURA DE PÍXELES
    process(clk)
        variable base_address : integer;
    begin
        if rising_edge(clk) then
            -- Coordenadas pixel art
            block_x <= pixel_x / 8;
            block_y <= pixel_y / 8;

            if (block_x < ROM_WIDTH) and (block_y < ROM_HEIGHT) then
                -- FORMULA MÁGICA DE DIRECCIÓN:
                -- (Frame Actual * Tamaño Frame) + (Fila * Ancho) + Columna
                base_address := current_frame * PIXELS_PER_FRAME;
                rom_address  <= base_address + (block_y * ROM_WIDTH) + block_x;
                
                color_data <= IMAGEN_ROM(rom_address);
            else
                color_data <= X"000";
            end if;
        end if;
    end process;

    red_out   <= color_data(11 downto 8);
    green_out <= color_data(7 downto 4);
    blue_out  <= color_data(3 downto 0);

end Behavioral;